"""Generated by AetherLab - thin-lens ray diagram (curated component)."""

import numpy as np
from manim import *


class AetherLabScene(Scene):
    def construct(self):
        # AetherLab explanation layer: concept, governing equation, what to watch.
        _intro_head = Text('Image formation by a converging lens', font_size=40, weight=BOLD, color=YELLOW)
        _intro_eq = Text('1/f = 1/u + 1/v', font_size=30, color=WHITE)
        _intro_watch = Text('Watch: the principal rays bend at the lens and meet\nagain where the image forms.', font_size=26, color=GREY_B)
        _intro = VGroup(_intro_head, _intro_eq, _intro_watch).arrange(DOWN, buff=0.5)
        if _intro.width > 12.4:
            _intro.scale_to_fit_width(12.4)
        if _intro.height > 7.0:
            _intro.scale_to_fit_height(7.0)
        self.play(FadeIn(_intro, shift=0.2 * UP), run_time=1.0)
        self.wait(1.8)
        self.play(FadeOut(_intro), run_time=0.5)

        f, do, di = 1.8, 3.6, 3.6
        ho, hi = 1.2, -1.2
        scene_scale = 1.0
        f, do, di, ho, hi = [v * scene_scale for v in (f, do, di, ho, hi)]

        title = Text('Thin-lens image formation').scale(0.46).to_edge(UP)

        def P(x, y):
            return np.array([float(x), float(y), 0.0])

        axis = Line(P(-6.4, 0), P(6.4, 0), color=GREY_B, stroke_width=2, stroke_opacity=0.6)
        lens = Ellipse(width=0.5, height=4.0, color=BLUE_C, fill_color=BLUE_E,
                       fill_opacity=0.25, stroke_width=2.5)
        f_near = Dot(P(-f, 0), color=GREY_A, radius=0.05)
        f_far = Dot(P(f, 0), color=GREY_A, radius=0.05)
        f_lbl1 = Text("F").scale(0.32).next_to(f_near, DOWN, buff=0.12)
        f_lbl2 = Text("F'").scale(0.32).next_to(f_far, DOWN, buff=0.12)

        obj = Arrow(P(-do, 0), P(-do, ho), buff=0, color=GREEN, stroke_width=4)
        img = Arrow(P(di, 0), P(di, hi), buff=0, color=RED, stroke_width=4)
        obj_lbl = Text("object").scale(0.3).next_to(obj, UP, buff=0.1)
        img_lbl = Text("real image (inverted)").scale(0.3).next_to(img, DOWN, buff=0.1)

        tip = P(-do, ho)
        itip = P(di, hi)
        # Ray 1: parallel to axis, then through the far focus F'.
        ray1 = VMobject(color=YELLOW, stroke_width=2.5)
        ray1.set_points_as_corners([tip, P(0, ho), itip])
        # Ray 2: straight through the lens centre.
        ray2 = VMobject(color=GOLD, stroke_width=2.5)
        ray2.set_points_as_corners([tip, P(0, 0), itip])
        # Ray 3: through the near focus F, emerging parallel to the axis.
        ray3 = VMobject(color=ORANGE, stroke_width=2.5)
        ray3.set_points_as_corners([tip, P(0, hi), itip])

        pulse = Dot(tip, color=WHITE, radius=0.06)

        self.play(Create(axis), Create(lens), run_time=0.9)
        self.play(FadeIn(f_near), FadeIn(f_far), FadeIn(f_lbl1), FadeIn(f_lbl2), run_time=0.5)
        self.play(GrowArrow(obj), FadeIn(obj_lbl), run_time=0.7)
        self.play(Create(ray1), Create(ray2), Create(ray3), run_time=2.0)
        self.add(pulse)
        self.play(MoveAlongPath(pulse, ray1), run_time=1.4, rate_func=linear)
        self.play(GrowArrow(img), FadeIn(img_lbl), run_time=0.8)
        self.wait(0.6)

        # AetherLab explanation layer: clear the stage, then explain what it showed.
        for _m in self.mobjects:
            _m.clear_updaters()
        if self.mobjects:
            self.play(FadeOut(*self.mobjects), run_time=0.8)
        _head = Text('What the animation shows', font_size=34, weight=BOLD, color=YELLOW)
        _eq = Text('1/f = 1/u + 1/v', font_size=28, color=WHITE)
        _facts = VGroup(Text('Focal length f = 1.80, object distance u = 3.60 → image distance v =\n3.60', font_size=25, color=GREY_A), Text('Magnification m = -v/u = -1.00', font_size=25, color=GREY_A), Text('The image is real and inverted, same size', font_size=25, color=GREY_A)).arrange(DOWN, aligned_edge=LEFT, buff=0.3)
        _key = Text('Two principal rays are enough to find the image, and the lens equation\nagrees.', font_size=27, color=TEAL_A)
        _key_box = SurroundingRectangle(_key, color=TEAL, buff=0.22, corner_radius=0.12)
        _card = VGroup(_head, _eq, _facts, VGroup(_key, _key_box)).arrange(DOWN, buff=0.42)
        if _card.width > 12.4:
            _card.scale_to_fit_width(12.4)
        if _card.height > 7.0:
            _card.scale_to_fit_height(7.0)
        self.play(FadeIn(_head, shift=0.2 * DOWN), FadeIn(_eq), run_time=1.2)
        self.play(LaggedStart(*[FadeIn(_f, shift=0.2 * RIGHT) for _f in _facts], lag_ratio=0.85), run_time=4.2)
        self.play(FadeIn(_key), Create(_key_box), run_time=1.2)
        self.wait(1.8)
